    {
      "statement": "Every retained transaction-period rate match also has a matching reporting-period exchange-rate row for the same account and source subsidiary.",
      "about": "data",
      "target": "int_netsuite__transactions_with_converted_amounts",
      "evidence_of_dependence": "JOIN intermediate.int_netsuite__accountxperiod_exchange_rate_map r ON r.accounting_period_id=b.transaction_accounting_period_id",
      "alternative": "The contract requires two rate joins and states: \"Both joins are required; rows missing either rate are excluded.\"",
      "importance": 5,
      "reason": "Without the omitted reporting-period join, lines lacking required reporting rates remain in the result.",
      "updates": null
    },
    {
      "statement": "The reporting-period exchange rate equals the transaction-period exchange rate for every retained line and reporting period.",
      "about": "data",
      "target": "int_netsuite__transactions_with_converted_amounts.exchange_rate_reporting_period and converted_amount_using_reporting_month",
      "evidence_of_dependence": "r.exchange_rate exchange_rate_transaction_period,r.exchange_rate exchange_rate_reporting_period",
      "alternative": "The contract requires the reporting rate to match on \"reporting_accounting_period_id\" and the transaction rate to match on \"transaction_accounting_period_id\".",
      "importance": 5,
      "reason": "Reusing the transaction rate changes reporting-month conversions whenever rates differ between periods.",
      "updates": null
    },
    {
      "statement": "The period and exchange-rate joins produce at most one output row for each transaction_line_id.",
      "about": "data",
      "target": "int_netsuite__transactions_with_converted_amounts",
      "evidence_of_dependence": "JOIN intermediate.int_netsuite__transaction_and_reporting_periods m ON m.accounting_period_id=b.transaction_accounting_period_id JOIN intermediate.int_netsuite__accountxperiod_exchange_rate_map r",
      "alternative": "The output contract specifies \"One row per transaction_line_id\", while the period mapping permits multiple reporting periods and the exchange-rate map includes to_subsidiary_id in its grain.",
      "importance": 4,
      "reason": "Multiple reporting periods or target subsidiaries can violate the required unique output grain even when source keys are unique.",
      "updates": null
    },
    {
      "statement": "Every non-null selected legacy exchange-rate string is parseable as DOUBLE.",
      "about": "data",
      "target": "int_netsuite__transactions_with_converted_amounts",
      "evidence_of_dependence": "b.unconverted_amount*try_cast(r.exchange_rate AS DOUBLE)",
      "alternative": null,
      "importance": 3,
      "reason": "Unparseable non-null rates silently yield NULL converted amounts without an established handling rule.",
      "updates": null
    },
    {
      "statement": "Comparing full-precision multiplier timestamps to the current time selects the same periods as first truncating those timestamps to seconds.",
      "about": "data",
      "target": "int_netsuite__transaction_and_reporting_periods",
      "evidence_of_dependence": "try_cast(m.starting_at AS TIMESTAMP)<=current_timestamp",
      "alternative": "The contract requires \"the multiplier's starting_at, truncated to seconds and interpreted as a timestamp\" to be no later than the current time.",
      "importance": 2,
      "reason": "A fractional-second timestamp near the evaluation boundary can be excluded despite qualifying after the required truncation.",
      "updates": null
    }
  ],
